insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 1, 'Integrity, as this course uses the word, is the discipline of doing what?', '["Keeping the well producing at the rate its completion was designed for.", "Keeping whatever is in the well inside it, which is containment rather than productivity or condition.", "Keeping every item of downhole hardware in a condition a maintenance engineer would sign off as good.", "Keeping the well efficient, so that the pressure drop from the reservoir to the sales point stays as small as it can be."]'::jsonb, 1, 'The lesson rules out productivity and efficiency by name, because a well can be fully contained and quite uneconomic.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 2, 'An answer about integrity is only an answer when it names which two things?', '["A wellbore diameter and a casing grade for the string in question.", "A regulator and the standard the operator has chosen to work the asset to for the current year.", "A test pressure and the length of time the element in question was held at that pressure during the last survey.", "A specific source of pressure and a specific place the fluid must not be allowed to reach."]'::jsonb, 3, 'Direction is what makes the statement checkable, and a claim with no named destination cannot be tested.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 3, 'Why does one barrier vocabulary cover drilling, production and abandonment alike?', '["A permanent plug does the job the BOP did, standing between a pressure source and somewhere it must not go.", "The three phases of a well are governed by the same pressure rating.", "Writing a single vocabulary was cheaper than writing three separate ones for the same well.", "Abandonment was folded into this engine late in its life, and the shared words are an accident of that history."]'::jsonb, 0, 'That is why the list of kinds puts the cement plug and the mechanical plug alongside the BOP and the Christmas tree.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 4, 'How is the published teaching well recorded, element by element?', '["Five in each envelope, every one of them verified.", "Six in the primary envelope and four in the secondary, with the Christmas tree entered as not verified.", "Five elements in each envelope, with nine verified and the downhole safety valve entered as degraded.", "Five in each envelope, with the downhole safety valve entered as failed, which is what moves the well off a clean bill of health."]'::jsonb, 2, 'No leak rate and no corrosion model were needed to reach that verdict, only a status and a rule for combining statuses.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 5, 'What makes a single barrier unacceptable on a well that can flow?', '["One barrier is harder to pressure test than a pair of them.", "The failure and the release are one event, so nobody is given an interval in which to notice and intervene.", "A lone barrier wears out faster, because it carries the whole differential on its own.", "One barrier leaves no way to measure a leak rate, and the engine needs a rate before it can categorise the well."]'::jsonb, 1, 'Two envelopes turn the first failure into something you respond to rather than something you report afterwards.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 6, 'How is a flowing well that carries only one envelope treated?', '["It fails the two envelopes check outright, because that check is written as a hard rule and not a warning.", "A warning is recorded and the run carries on to the category.", "The whole run is refused, with the missing envelope named in the error that comes back.", "The well is downgraded by exactly one step from whatever the single surviving envelope would otherwise have earned."]'::jsonb, 0, 'The rule is hard because two independent envelopes is the requirement itself rather than a preference.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 7, 'Across the sixteen combinations for a well with flow potential, how often does green come back?', '["Four times, once for every combination holding an intact primary.", "Three times, matching the number of yellow results in the same table.", "Twice, once where both envelopes are intact and once where the primary is intact and the secondary merely degraded.", "Exactly once, and only where both envelopes are intact, with yellow three times and orange seven times."]'::jsonb, 3, 'Red appears five times, so the table is a good deal less forgiving than most barrier drawings suggest.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 8, 'An intact primary sitting above an empty secondary is categorised how?', '["Green, since nothing in the well has actually failed.", "Yellow, on the grounds that a missing envelope is a degradation and not a failure.", "Orange, because a well required to carry two envelopes is in fact carrying only one of them.", "Red, because the absence of a whole envelope is punished more harshly than the failure of one element inside one."]'::jsonb, 2, 'The intact and failed pairing lands on orange too, so a missing barrier and a broken barrier come out level.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 9, 'Independence between the two envelopes is what sort of claim?', '["An engineering claim about the design, which the engine cannot measure from the element records it holds.", "A calculated result the rollup returns for each envelope.", "A regulatory requirement, checked by comparing the two lists for shared failure mechanisms.", "A property derived from element kinds, since two elements drawn from the same kind group cannot be independent."]'::jsonb, 0, 'What the engine can see is an element listed as serving both envelopes, and it names every one of those.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 10, 'In the envelope rollup, which element decides the result?', '["The deepest one, because it faces the pressure source directly.", "The worst one, and an element nobody has tested counts as a degradation rather than as nothing at all.", "An average of the four statuses, weighted by how many elements hold each of them.", "The most recently tested one, since the newest evidence about the envelope is the evidence worth acting on."]'::jsonb, 1, 'That is why an envelope needs everything in it tested and passed before it can read intact.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 11, 'Alongside the limit itself, what does the annulus pressure calculation report?', '["A leak rate for the annulus once the stated limit is exceeded.", "A bleed schedule for bringing the annulus back below its limit.", "The governing element, being the lowest row once each candidate limit is worked in differential form.", "The remaining life of the weakest string, as the number of years before its limit falls below operating pressure."]'::jsonb, 2, 'The same arithmetic runs under the API RP 90 convention, with default factors of 0.5, 0.8 and 0.75 by role.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 12, 'Which of these is a permanent barrier rule the engine actually tests?', '["A cement plug of 30 m measured depth, whatever it is set on.", "A surface plug of 100 m, with no reduction allowed for a foundation beneath it.", "An annular cement column of 50 m where a log verifies it, rising to 100 m where the annulus has never been logged.", "A cement plug of 100 m measured depth, or 50 m where it sits on a verified mechanical foundation."]'::jsonb, 3, 'Annular cement is 30 m where a log verifies it and 100 m where nothing does, so the log buys most of the length.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 13, 'Which question is refused on the grounds that there is no time axis?', '["How fast the element in question is leaking at present.", "How long the well has got, since a degraded element is degraded today and tomorrow is not modelled.", "How much the intervention to repair the element will cost the asset.", "How likely the element is to fail, which would need a probability that a lookup table over statuses never carries."]'::jsonb, 1, 'Corrosion is refused for the same sort of reason: any wall loss has already been priced into a status by a person.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 14, 'An engineer pastes an element status straight into the categoriser instead of rolling the envelope up first. Before this course, what came back?', '["A clean green verdict, on a well whose primary envelope nobody had actually checked.", "An immediate refusal naming the wrong word.", "A yellow verdict, on the reasoning that an unrecognised status ought to be treated the same way an unverified element is treated.", "The primary envelope alone, with the secondary quietly dropped from the calculation and no note of it anywhere in the output."]'::jsonb, 0, 'One half of that boundary already refused an unknown word and the other trusted it. The trusting half was the bug.'),
  ('integrity', 'beginner', 'module', 'm01-what-this-course-decides', 15, 'The abandonment builder describes itself as which of these?', '["A fully operational procedure written for the plugging crew.", "A cost estimate for the abandonment, priced from the material takeoff it produces.", "A planning checklist in the well programme tradition, rather than a procedure for running the job.", "A regulatory submission, complete enough that its phased step list can be filed as the abandonment programme."]'::jsonb, 2, 'It will tell you a zone needs a second barrier and will not tell you what to do when the plug refuses to tag.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 1, 'A barrier element record carries three load bearing parts. Which three?', '["A depth, a pressure rating and the date of its last test.", "A kind, a manufacturer and the inspection interval the operator has assigned to it.", "A thing with a name and a kind, a job saying which envelope it serves, and a status of its own.", "A name, a depth and an envelope, with the status worked out by the engine from the kind and the installation date."]'::jsonb, 2, 'Only the status changes over the life of the well, which is why it is the field a barrier table gets wrong.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 2, 'What becomes of an element that arrives with no envelope assignment?', '["The engine refuses that element by name and stops, because it will not infer the job from the kind.", "The engine defaults the element into the primary envelope.", "The engine places it in whichever envelope holds fewer elements when it is read.", "The engine warns, leaves the element out of both rollups, and carries on to the category with what it can place."]'::jsonb, 0, 'The same packer can be primary in one well and secondary in the next, so there is nothing there to infer from.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 3, 'Why are the fourteen element kinds grouped into six families?', '["The engine keeps the kinds in six separate lists internally.", "Because the family decides which envelope an element of that kind belongs to.", "Because each family carries its own verification interval, which the engine reads when deciding whether a test is current.", "Two kinds in one family tend to fail the same way and to be verified by the same sort of test."]'::jsonb, 3, 'That bears on independence, since two elements from one family are weaker evidence of it than two from different ones.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 4, 'Which kinds make up the family that is a barrier only in the closed position?', '["The wellhead, the tubing hanger and the packer.", "The downhole safety valve, the Christmas tree and the BOP, which is why these get function tested.", "The casing and the completion string, the two long pressure vessels with a wall rating.", "The cement plug and the mechanical plug, since neither does anything until it has been set and tagged in the hole."]'::jsonb, 1, 'A seal is pressure tested, a valve is function tested, and a cement plug is logged or tagged, family by family.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 5, 'The envelope field accepts exactly which set of values?', '["Primary and secondary, since an element serves one job.", "Primary, secondary, both or none, with none reserved for retired hardware.", "Primary, secondary or both, with anything else refused and the offending element named in the error.", "Primary, secondary, shared or unassigned, the last letting an element be written down before its job is settled."]'::jsonb, 2, 'There is no default and no inference, so a barrier table cannot be half filled in and still be run.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 6, 'On a producing well, what does the secondary envelope usually consist of?', '["The production path, from the sand face up to the safety valve.", "The annulus side: the casing and its cement, the wellhead, the tubing hanger and the tree on top.", "The BOP stack together with the kill weight fluid column standing above the reservoir.", "Whatever elements were left over once the primary envelope had been drawn, which is why it is called the backup."]'::jsonb, 1, 'It has to lie outside the primary and wrap it, because it contains the fluid once the primary lets go.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 7, 'The production casing appears in both envelopes of the published roster. Why is that right?', '["Below the packer the string faces reservoir pressure, and above it the same steel faces the annulus.", "Because the string is long enough to reach into both envelopes.", "Because a casing string is always recorded twice, once for burst and once for collapse.", "Because the engine wants equal counts in the two envelopes, and splitting the string is how the roster reaches five each."]'::jsonb, 0, 'Two elements, two jobs and two status entries sit on one piece of steel with a packer between the roles.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 8, 'What is done with an element marked as serving both envelopes?', '["The roster is refused, with the element named in the error.", "It is counted once, in the primary, and the sharing is noted in the reason string.", "It is split into two records carrying half the rating each, so that neither envelope is credited with the whole of it.", "It is pushed into both lists, and its name is collected into a separate list of shared elements."]'::jsonb, 3, 'The published roster has an empty shared list, so the check for shared elements passes cleanly on it.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 9, 'Why is the shared element check raised as a warning rather than as a hard failure?', '["Because the check runs before any element status has been read.", "Some wells genuinely cannot avoid one, so the convention makes it acceptable by deliberate dispensation.", "Because a shared element usually turns out to be one element recorded twice by mistake.", "Because the rollup already punishes the sharing through the category, so failing a check as well would count it twice."]'::jsonb, 1, 'The dispensation has to record who knew, why the sharing was unavoidable, and what compensates for it.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 10, 'Suppose the wellhead is marked as serving both envelopes and then fails. What category follows?', '["Yellow, because one element cannot fail two envelopes at once.", "Orange, the same answer the roster gives when the safety valve alone fails.", "Red, since the failure enters both lists and two failed envelopes on a flowing well is the worst reading.", "Green, because the wellhead is the one element the convention allows to be shared, so its failure is dispensed with."]'::jsonb, 2, 'The reason given names one barrier envelope failing while the other is degraded, failed or missing.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 11, 'How should an envelope be drawn in the first place?', '["From the pressure source outward, following every path the fluid could take until something closes it.", "By listing the equipment in the well that you trust the most.", "By copying the element list from the last well built to the same completion design.", "By working down from surface, since the tree and the wellhead are the elements whose condition is easiest to establish."]'::jsonb, 0, 'A table built from a drawing can be trusted, while a drawing reconstructed from a table usually cannot.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 12, 'What must a complete envelope terminate in?', '["A verified element of any kind, tested within its interval.", "The shallowest casing shoe, above which containment is no longer required.", "A pressure gauge, so that the annulus behind the terminating element can be watched for the pressure that signals a leak.", "Something that can be closed, at surface or at the mudline, because containment ending in open pipe is none."]'::jsonb, 3, 'It also has to enclose the source on every side, including behind the casing where cement does work you cannot see.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 13, 'Three verified elements that do not join into anything roll up as what?', '["Empty, on the grounds that no envelope was really formed.", "Degraded, because the engine spots the gap and drops the envelope one step.", "Intact, because every element listed passed and geometric closure is not something the engine checks.", "Failed, since a check that the elements seal to one another is one of the four named rule checks in the routine."]'::jsonb, 2, 'The quiet failure mode is a table that passes while the drawing it was never checked against would not.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 14, 'Which sort of missing thing does the engine genuinely catch?', '["An envelope holding no elements at all, which rolls up as empty and drops a flowing well to orange.", "A gap between two elements that ought to have sealed together.", "An element whose depth leaves the pressure source outside the envelope it belongs to.", "A path behind the casing that no cement covers, found by comparing the cement tops against the depth of the source."]'::jsonb, 0, 'Populated but not closed is the case it cannot see, which is why the sketch has to come before the table.'),
  ('integrity', 'beginner', 'module', 'm02-elements-and-envelopes', 15, 'What is being claimed when an element is written down as verified?', '["That the element was installed to the correct specification.", "That somebody tested it, that the test passed, and that the result has not yet aged out of currency.", "That the element looks right on the most recent inspection of the wellhead area.", "That the element has been calculated to withstand the differential it would see if the other envelope let go."]'::jsonb, 1, 'An element that has never been tested is not verified, which differs from failed and differs again from absent.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 1, 'How many statuses may an element carry, and what happens to a fifth word?', '["Four, exported as ELEMENT_STATUSES, and any word outside that list is refused rather than interpreted.", "Three, because not verified is handled as a missing element.", "Four for an element and four for an envelope, drawn from one shared list of words.", "Five, once empty is counted, that being the value taken when nobody has assigned the element anything at all."]'::jsonb, 0, 'An envelope has four words of its own, and two of them overlap the element list, which is where confusion starts.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 2, 'What does the rollup do with a status word it does not recognise?', '["It ignores that element and rolls up the rest.", "It substitutes not verified, on the ground that an unreadable claim is no claim.", "It throws, naming both the unrecognised word and the element that carried it into the roster.", "It returns green with a warning attached, which is the behaviour callers have always relied on for legacy rosters."]'::jsonb, 2, 'Silently ignoring the word would force a guess about a barrier, and every guess available is wrong.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 3, 'How do the four statuses rank against one another?', '["Verified, then not verified, then degraded, then failed.", "Verified first, then degraded and not verified level with each other, and failed last of all.", "They do not rank, because the rollup averages them across the elements in the envelope.", "Failed first as the most urgent, then degraded, then not verified, with verified at the bottom as the resting state."]'::jsonb, 1, 'An element never sits between two of them, and whoever holds the test evidence picks exactly one.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 4, 'The label on the verification check names which pair of tests?', '["A pressure test and a function test of the same element.", "A shop test before delivery and a commissioning test after handover.", "An inflow test and a positive test, the pair expected before an element may be recorded as verified at all.", "An initial test at installation and a periodic one since, on whatever interval the element and well require."]'::jsonb, 3, 'The claim is therefore about a document rather than about a component somebody has looked at.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 5, 'In what way can an element stop being verified though nothing physical happened?', '["Its test expired, so no new evidence arrived and the element drops to not verified on the clock alone.", "It was reassigned from the primary envelope to the secondary.", "The engine downgrades it once a second element in the same envelope goes degraded.", "It is re-rated to degraded, because an ageing test result counts as bad evidence rather than as no evidence."]'::jsonb, 0, 'The other route out of verified is new evidence that is bad, which lands the element on degraded or on failed.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 6, 'Why does the all verified check pass on the published roster?', '["Because the whole roster is verified.", "That check asks only whether an element sits at not verified, and the degraded valve has evidence of its own.", "Because the degraded element sits in the primary envelope.", "Because the check is evaluated before the rollup runs, at a point where no element has yet been re-rated."]'::jsonb, 1, 'Re-rate that same valve to not verified and the check begins failing, listing the element by name.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 7, 'An element set to not verified gives which envelope verdict?', '["Empty, since an untested element cannot be counted at all.", "Failed, because a barrier nobody can demonstrate is not a barrier.", "Degraded, exactly as an explicitly degraded element does, and the category is yellow in both cases.", "Intact, provided every other element in the list is verified, because absence of evidence is treated as neutral."]'::jsonb, 2, 'The engine even hands back the same sentence for both, citing degradation or unverified elements and no failure.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 8, 'What separates an untested element from a degraded one in the output?', '["Only the checks list, in which the all verified check fails and names the element that has no current test.", "The envelope status, which is worse for the untested element.", "The category, which drops one further step when the element has never been tested.", "The reason string, which spells out that no test exists instead of reporting a measured shortfall in performance."]'::jsonb, 0, 'That difference is the remedy: a test may clear the unverified element, while a degraded one needs an intervention.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 9, 'Why is not verified the status people quietly round down to verified?', '["The two words sit next to one another in the status list.", "The engine treats the two identically, so the entry makes no difference.", "Because an unverified element costs as much as a failed one, and few engineers will sign a roster that reads as failed.", "Nothing seems wrong, the thing has always worked, and none of that is evidence the engine will accept."]'::jsonb, 3, 'An envelope holding an unverified element is a degraded envelope, and the well on that roster is yellow.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 10, 'Degraded asserts two things at once. Which two?', '["That the element has failed and that it has been tested.", "That the element is untested and that its condition is unknown.", "That the element is not performing to its specification and that it is nonetheless still performing.", "That the element is impaired and that the impairment was measured closely enough to put a leak rate against it."]'::jsonb, 2, 'Degraded is a measured shortfall while failed is an absence, and that is the whole of the difference.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 11, 'On the published roster, how do the four rule checks come out?', '["One of them fails, naming the downhole safety valve.", "Every one of them passes, because the yellow verdict comes from the rollup and not from the checklist.", "Two fail, the all verified check and the no failed elements check together.", "Three pass and the fourth is skipped, since the shared element check only runs when an element is marked as both."]'::jsonb, 1, 'The checklist is a list of specific defects and carries no line at all for a degraded element.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 12, 'A degraded primary standing against a failed secondary earns which category?', '["Red, because one envelope has failed while the other is merely degraded rather than intact.", "Empty, because a failed envelope no longer counts as one.", "Yellow, the same result a degraded primary earns on its own.", "Orange, since one envelope failing is orange whatever the other is doing, and degradation adds nothing to that."]'::jsonb, 0, 'A degraded element is your margin, spent, and it becomes urgent the moment anything else goes wrong.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 13, 'How does the rollup behave the moment it meets a failed element?', '["It notes the failure and continues to the end of the list.", "It counts failures and fails the envelope only when two or more are found.", "It weighs the failed element against the verified ones around it and returns degraded when the verified ones win.", "It returns failed at once and stops walking the list, since nothing remaining could change the answer."]'::jsonb, 3, 'That short circuit is the rule written as code: one failed element ends its envelope outright.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 14, 'Re-rating the published safety valve to failed produces which result?', '["A failed primary, a failed secondary and a red category.", "A failed primary, an intact secondary, orange, and a no failed elements check that names the valve.", "A degraded primary, an intact secondary and a yellow category as before.", "A failed primary and an intact secondary, categorised as red, because a flowing well with one envelope left is worst."]'::jsonb, 1, 'The reason reads that one envelope failed while the other is intact, and that is what keeps the well off red.'),
  ('integrity', 'beginner', 'module', 'm03-status-and-what-it-means', 15, 'What makes the call between failed and degraded the sharpest judgement on this tier?', '["It is the only status the engine can compute for itself.", "It is the status a regulator reviews first when an incident is investigated.", "It is the one status that ends an envelope''s contribution instantly, and the engine takes it as given.", "It is the only status that cannot be reversed, because an element recorded as failed leaves the roster for good."]'::jsonb, 2, 'Where a result is genuinely ambiguous, degraded and not verified both leave the envelope degraded anyway.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 1, 'A reviewer proposes scoring an envelope as the percentage of its elements that carry a verified status. Why does the rollup refuse that?', '["Percentages are awkward to audit inside a barrier table.", "The engine holds no field for element importance, so any percentage it produced would be meaningless to somebody reviewing it.", "Pressure has to get past every element but only needs to beat one, so a chain with one broken link is broken.", "Roster lengths differ from well to well, so a percentage could not be compared across a field."]'::jsonb, 2, 'The rollup takes no input for importance or size, and that omission is deliberate: an element that was not load bearing would not be in the envelope at all.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 2, 'The published primary envelope holds 5 elements, four verified and the DHSV degraded. What verdict does it return?', '["Degraded, because the worst status present sets the verdict for the whole envelope rather than for one row.", "Intact, since four of the five elements are verified.", "Mostly intact, with the degradation recorded against the safety valve alone rather than against the envelope that contains it.", "Failed, because a degraded downhole safety valve cannot hold pressure by itself."]'::jsonb, 0, 'The secondary envelope on the same well also holds 5 elements, all of them verified, so it reads intact: one bad element decides which is which.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 3, 'In what order are the tests applied before an envelope verdict is returned?', '["Failed first, then empty, then intact, then degraded.", "Each status is counted in turn and the verdict is whichever status appears most often across the elements listed.", "Degraded first, so that a degradation is never hidden behind a failure elsewhere in the same envelope.", "Empty first, then any failed element, then any degraded or not verified one, and intact only if nothing matched."]'::jsonb, 3, 'First match wins, which is exactly why a single degradation beats any number of verified elements sitting beside it.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 4, 'Two verified elements sit in an envelope on their own. Which word describes that envelope?', '["Verified, the same word the two elements carry.", "Intact, since an envelope is intact, degraded, failed or empty and is never called verified.", "Either word serves, because verified and intact are the two vocabularies naming one fully demonstrated condition.", "Qualified, which is what the engine returns once nothing in an envelope is outstanding."]'::jsonb, 1, 'Two of the four words overlap between the vocabularies and two do not, and the two that do not are precisely the ones that would let a part be mistaken for a whole.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 5, 'What did wellCategory answer when it was handed the element status not verified in an envelope slot?', '["Green, because the string was not recognised and fell through to the branch that reports a clean well.", "An error naming the element vocabulary.", "Yellow, since the function mapped anything it did not recognise onto the nearest degradation before returning a colour.", "Orange, on the grounds that an unreadable envelope status left only one envelope it could trust."]'::jsonb, 0, 'The result was a clean bill of health for a well whose primary envelope nobody had checked, which is the one direction an integrity function must never fail in.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 6, 'While its sibling was still answering for strings it did not know, how did the rollup behave on an unknown element status?', '["It returned empty and recorded a warning.", "It quietly dropped the offending element, which shortened the count and left the surviving elements to decide the verdict.", "It had always thrown, so two halves of one boundary disagreed about whether to trust their caller.", "It fell through in the same way, and both functions were repaired together for that reason."]'::jsonb, 2, 'Both refuse now, and the message names the other vocabulary and tells you to roll your elements up first.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 7, 'One row of a barrier table is declared as serving both envelopes. Where does the engine put it?', '["Into the primary list only, with a note recorded against it.", "Into the primary list and the secondary list, so its status is read once for each envelope verdict.", "Into a third list of shared hardware, which the rollup consults after both envelope verdicts have already been settled.", "Into whichever list is shorter, so the two envelope counts stay as close to balanced as they can."]'::jsonb, 1, 'One piece of steel appears in two chains, so both verdicts move together whenever its condition changes.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 8, 'How does a fully compliant two barrier well arrive at red on a single event?', '["The category weights any failure twice on a flowing well.", "A failure in the primary is recorded against the secondary as well, and stays there until the secondary has been retested.", "The two envelopes check turns from warn level to fail level the moment any element in the well is failed.", "A shared element lies in both chains, so its failure fails the two envelopes at the same instant."]'::jsonb, 3, 'The reason given is that one barrier envelope failed and the other is degraded, failed or missing, and the spare bought nothing because it was never a second thing.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 9, 'At what level is the check for no element shared between envelopes reported?', '["Fail, the same level as the missing envelope check.", "It is not a check at all, merely a note printed beside the seat counts whenever the two totals fail to agree.", "Warn while the well can flow, and fail once the flow potential flag has been cleared.", "Warn, because a common element is not forbidden and may be accepted by documented dispensation."]'::jsonb, 3, 'Warn level stops you sharing an element by accident without taking the acceptance decision out of your hands.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 10, 'Add the primary count to the secondary count, then subtract the number of physical elements on the roster. What has that found?', '["The number of envelopes missing from the well.", "The count of elements serving both envelopes, which is the length of the shared list the engine returns.", "The number of unverified elements, on the reasoning that such an element fills a seat without qualifying to occupy it.", "Nothing useful, since the roster and the two envelope lists are built from separate inputs."]'::jsonb, 1, 'Each element contributes one seat if it serves one envelope and two if it serves both, so the excess counts the shared ones exactly.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 11, 'Primary count 5, secondary count 5, roster length 10. What does that arithmetic establish?', '["Nothing is shared, so the two envelopes are two independent chains rather than one chain listed twice.", "Every element on the well has been verified.", "The envelopes are balanced in size, which is the condition the two envelopes check is actually testing for.", "The roster is complete, because a missing element would show as a gap between the two counts."]'::jsonb, 0, 'Independence can be established from three numbers without reading a single element name.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 12, 'Why does the module put the seat arithmetic ahead of reading any status column?', '["Counting is quicker than reading a status column.", "The engine will not roll an envelope up until the seat total and the roster length have been reconciled by hand first.", "Statuses describe the condition of what you have, whereas the gap tells you what you have at all.", "A positive gap changes the rollup rule, which then takes the better of the two readings on a shared row."]'::jsonb, 2, 'Where the gap is not zero, everything downstream has to be read knowing that some rows move in lockstep.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 13, 'What does the two column layout of a barrier table assert, whether or not it happens to be true?', '["That the well has two envelopes, since every such table carries a primary column and a secondary one.", "That the primary envelope was drawn up first.", "That each element has been tested at least once, because a table with no evidence behind it would not have been issued for review.", "That the elements listed form a sealed surface around the flow source at the depths given."]'::jsonb, 0, 'The seat gap ignores the layout and asks instead how many distinct things the well actually contains.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 14, 'Why must both rollups be finished before the verdicts are handed to the category?', '["The category needs the seat gap as a third input.", "The category reads the element list a second time to work out which of the two envelopes was the more badly affected.", "An element status handed to the category is quietly treated as its nearest envelope equivalent.", "No element detail enters the category step, which takes two envelope words and returns one colour."]'::jsonb, 3, 'Passing an element status at that step now raises an error rather than returning a colour of any kind.'),
  ('integrity', 'beginner', 'module', 'm04-the-envelope-verdict', 15, 'All 4 named checks pass on the published roster and the well is still yellow. How should that be read?', '["As a defect, because passing checks ought to give green.", "As a sign the flow potential flag was left set, since a well passing every check cannot be yellow once that flag is cleared.", "The checks are the work list and the colour is what the well is, so passing them is not a score.", "As a rounding, since yellow is what the engine returns whenever no check has been failed outright."]'::jsonb, 2, 'The every element verified check looks for unverified rows, and the DHSV is degraded rather than unverified, so nothing on the list fires.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 1, 'A colleague asks whether the number of elements in each envelope changes the traffic light. What is the answer?', '["Yes, a larger envelope earns a better colour.", "No, only the primary verdict and the secondary verdict reach that step, and nothing else does.", "Yes, because an envelope holding more elements counts as more redundant and the engine softens its colour by one step.", "Only where the two envelopes hold different numbers, which is read as a sign of an incomplete roster."]'::jsonb, 1, 'How badly the degraded element was degraded does not reach it either, nor which of the fourteen kinds it happened to be.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 2, 'Why is the verdict published as a colour instead of a score out of ten?', '["Colours print more clearly on a barrier schematic.", "The four element statuses cannot be placed on a numerical scale, so any score produced from them would have to be arbitrary.", "A score would have to take in the element counts, which the category step deliberately never sees.", "A score invites averaging and trending, and containment is not a quantity that partial credit can describe."]'::jsonb, 3, 'Each colour maps to a defined obligation, so reaching one commits somebody to an action rather than to a line in a report.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 3, 'Green comes back on a well whose elements were last pressure tested ten years ago. What has the category not looked at?', '["Evidence quality, because an element verified this morning and one verified long ago are the same word here.", "The number of elements in each envelope.", "The test interval carried by each element, which is read and compared against today''s date before a verified status is accepted.", "The primary envelope, which stops being consulted once every element it holds carries a verified status."]'::jsonb, 0, 'Geometric closure is the other thing outside its reach, and the engine says so plainly rather than pretending to check your drawing.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 4, 'What question does the flow potential flag actually answer about a well?', '["Whether the well is currently producing to a facility.", "Whether hydrocarbons remain behind the casing, irrespective of the head of the fluid column standing in the wellbore.", "Whether the well, left alone, can deliver fluid to surface without anything further being done to it.", "Whether the primary envelope has been drawn around a permeable source rather than around the completion."]'::jsonb, 2, 'A well depleted below the head of the column standing in it cannot flow, and neither can one with no permeable source behind casing.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 5, 'Take the flow potential away and the requirement drops from two envelopes to one. What is the reasoning behind that?', '["One envelope is cheaper to verify each year.", "The secondary is normally built from surface hardware, and surface hardware cannot be reached once a well has been secured.", "Two envelopes are required only while a well is on production, and any shut in well is treated as unable to flow.", "The spare exists because a flowing well needs one, so a well that cannot flow has no use for it."]'::jsonb, 3, 'Deciding a well cannot flow is an engineering judgement about reservoir pressure, and the engine takes your word for it.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 6, 'With the flag cleared, how does the engine treat the secondary envelope verdict?', '["It weighs it at half the weight of the primary.", "It stops consulting it at all, so the colour becomes a function of the primary envelope alone.", "It reads it only where the primary is empty, that being the one case in which a second envelope is still required.", "It swaps the two, so the better of the pair is treated as the primary for the purpose of the colour."]'::jsonb, 1, 'That is the reverse of the flowing case, where the table is symmetric and the engine never asks which envelope failed.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 7, 'Somebody expects the flag to matter only where an envelope is missing. Which states does that reading miss?', '["States in which both envelopes have failed.", "States in which the primary is empty, that verdict being the one the engine refuses to categorise on its own.", "Every state in which the secondary is worse than the primary, since an unread secondary cannot drag the colour down.", "It misses nothing, because with two envelopes present the requirement is met either way."]'::jsonb, 2, 'An intact primary against a failed secondary is orange while the well can flow and green once it cannot.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 8, 'Nothing at all has been recorded in either envelope and the well is marked unable to flow. What comes back?', '["Orange, because an empty primary is a finding in its own right and one envelope is still not none.", "Green, since a single qualified barrier suffices.", "Red, on the reasoning that a well with no recorded barrier envelope is treated as two failed envelopes at once.", "Yellow, on the grounds that a missing record is a degradation rather than a failure of anything demonstrated."]'::jsonb, 0, 'That branch used to fall through to green, so a well nobody had recorded came back clean with a reason naming a barrier that did not exist.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 9, 'Why does the module insist that green admits no near miss and no rounding up?', '["Because the other three colours divide the remaining states evenly.", "Because a colour is rounded down whenever a check fails, so a well can drop out of green with no envelope verdict having moved.", "It occupies one state, both envelopes intact, and any lesser verdict in either envelope leaves it.", "Because green is withheld until a second verification cycle has been completed on both of the envelopes."]'::jsonb, 2, 'Yellow holds 3 of the sixteen flowing states and orange holds 7, so the classes sitting above green are anything but narrow.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 10, 'Orange covers two situations that look nothing alike on a schematic. What do they have in common?', '["Each leaves exactly one thing standing between the reservoir and the environment, with no spare behind it.", "Each involves an element that nobody has tested.", "Each arises from a failure somewhere in the well, which is why orange sits beside red in the scheme rather than beside yellow.", "Each is reached only where the two envelope verdicts differ from one another."]'::jsonb, 0, 'Orange is the largest class in the flowing table, holding 7 of the sixteen states.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 11, 'A failed envelope on its own is orange. What is needed to turn it red?', '["A second failure inside the same envelope.", "An expired restoration date, since an orange well turns red once the plan on file lapses without the envelope being restored.", "A shared element between the envelopes, because the failure then belongs to both of them at once.", "A partner that is degraded, failed or missing, which leaves no envelope you can still stand behind."]'::jsonb, 3, 'Red accounts for 5 of the sixteen flowing states, and every one of them holds at least one failed envelope.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 12, 'Swap the primary and secondary verdicts in any row of the flowing table. What happens to the colour?', '["It shifts one step towards red.", "It does not move, because the engine asks how many qualified envelopes remain, not which one failed.", "It changes wherever the primary is the worse of the two, a degraded primary being treated as the more serious case.", "It becomes undefined, the two slots not being interchangeable inputs to the function."]'::jsonb, 1, 'That symmetry is the opposite of the no flow case, where the primary decides everything and the secondary is never read.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 13, 'Empty against empty on a flowing well returns orange rather than red. Why is that?', '["The rule that fires is the missing second envelope, and nothing has been demonstrated to have failed.", "Because an empty envelope is scored as intact.", "Because red is kept for producing wells, and a well with no recorded envelope is presumed to have been shut in already.", "Because two empty envelopes cancel, leaving the engine no verdict it is able to act upon."]'::jsonb, 0, 'It therefore sits in the same class as a well with one good envelope, the scheme categorising only what is known.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 14, 'A well has sat yellow for two years while a repair keeps being deferred. What does the colour oblige?', '["An immediate shut in and intervention.", "Nothing beyond the periodic verification programme, since both envelopes still contain the source and production may continue.", "A written record of what is degraded, why operating is acceptable, what restores it and by when.", "A dispensation from the regulator, without which the well may not run past the first missed test date."]'::jsonb, 2, 'A yellow well with no restoration plan, and no expiry on that plan, is being managed by hope.'),
  ('integrity', 'beginner', 'module', 'm05-the-well-category', 15, 'Orange has come back on a well. Where do the hours or days you have to act come from?', '["From the test interval on the failed element.", "From the category table itself, which pairs every colour with a maximum period before the well must be made compliant.", "From the flow potential flag, a well that can flow being given a shorter window than one that cannot.", "From the operator''s own well integrity management system and from the regulator, not from the engine."]'::jsonb, 3, 'Deadlines differ by jurisdiction and by well, so the engine gives you the colour and stops there.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Tunde''s data sheet lists 4 elements in each envelope and 7 distinct pieces of hardware. What does he settle before going further?', '["The roster has lost a row and must be reissued.", "The two envelopes are unbalanced, so he ought to move a row out of the primary column before rolling anything up.", "Nothing yet, because a seat total and a hardware count are not expected to agree on any well.", "One element is serving both envelopes, since the seat total runs one ahead of the hardware count."]'::jsonb, 3, 'Seats minus distinct hardware equals the number of rows declared as serving both, exactly and not approximately.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 2, 'A reviewer writes on Adaora''s submission that an envelope showing no failures and no degradations must be intact. Where has the reviewer gone wrong?', '["Intact is not a word applied to envelopes at all.", "A not verified row degrades an envelope as surely as an observed impairment does, so intact does not follow.", "Envelopes are never intact on a flowing well, the flowing branch requiring two of them before it will say so.", "Degradation is only counted once a periodic test has fallen due, and the sheet she submitted records no dates."]'::jsonb, 1, 'This is the check people fail, because a roster with nothing bad written on it looks clean at a glance.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Before touching the panel, which part of the capstone should Ibrahim work on paper, and why that part?', '["The category, so he has a colour to test the panel against.", "The rollups, because the panel will not display an envelope verdict until every element has been given a status by hand.", "The split by envelope and the seat arithmetic, since that step is pure bookkeeping and gates everything after it.", "The obligation, so that an action is written down before any colour can influence what he recommends."]'::jsonb, 2, 'Where his answer and the panel disagree, the cause is almost always a shared element that was counted once instead of twice.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Grace hands the category function the word verified and it refuses her. What step has she skipped?', '["The rollup, since the category accepts envelope words and verified belongs to the element vocabulary.", "The flow potential flag, which carries no default.", "The seat arithmetic, which has to close before the engine will accept either of the two verdicts it is handed.", "Nothing further, because verified is a legitimate envelope word and the refusal is pointing at her secondary instead."]'::jsonb, 0, 'The message names both vocabularies and tells her to roll her elements up first.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 5, 'Femi''s flowing well shows an intact secondary and no rows recorded against the primary at all. What does he report?', '["Green, on the strength of the intact secondary.", "Orange, because an envelope with nothing in it is empty and that alone rules out green here.", "Yellow, treating an unrecorded envelope as a degradation until somebody confirms whether the rows exist and were simply not typed in.", "Red, on the reasoning that a missing envelope leaves less containment than an envelope that has merely failed."]'::jsonb, 1, 'Empty is not a small number, and the scheme categorises what is known rather than guessing at what nobody wrote down.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 6, 'An auditor asks Priya what the word verified on her sheet is actually asserting. What should she answer?', '["That a test result is on file for that element and that the result is still inside its interval.", "That the element was built to the correct specification.", "That the element has been inspected within the past year by somebody independent of the operating team, whatever its interval says.", "That the element is physically sound, which is a statement about steel rather than about paperwork."]'::jsonb, 0, 'Read all four statuses that way and the rest of the tier reduces to one sentence about the weakest claim an envelope holds.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 7, 'Two rows on Marcus''s table read failed and not verified. What separates those two claims?', '["The first is recoverable and the second is not.", "The first sits in the primary envelope and the second in the secondary, which is why the two are written up differently.", "Only severity, since both describe an element that has been examined and found wanting in some degree.", "Somebody looked and found the first not containing, while nobody can show anything at all about the second."]'::jsonb, 3, 'They differ as claims about evidence and they differ in the rollup too, failed beating degraded whenever both are present.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Kwame''s review note says the well lost its independence without losing a single element. What is he pointing at?', '["An envelope drawn without terminating in a formation.", "An envelope whose elements were all tested on one day, so their intervals fall due together and lapse as a group.", "A row declared as serving both envelopes, so one event can take both chains down together.", "A well whose secondary holds fewer rows than its primary, leaving the shorter of the two chains to govern."]'::jsonb, 2, 'The check that catches it sits at warn level, a common element being acceptable by deliberate and documented dispensation.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Helen finds an old report giving green for a well whose primary envelope had never been checked. What produced that?', '["An element status passed where an envelope status belonged, unrecognised and let through to a clean answer.", "A flow potential flag left cleared on a live producer.", "A rollup that read an untested element as verified, so the primary came back intact and the colour followed honestly from that.", "A barrier table whose primary column had been copied from the secondary during an earlier revision."]'::jsonb, 0, 'Its sibling had always refused an unknown element status, so two halves of one boundary disagreed about trusting their caller.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 10, 'Rosa is asked at her appraisal what this tier qualifies her to do unaided. Which claim is fair?', '["Sign off a permanent abandonment programme.", "Set the allowable surface pressure on an annulus once the governing element and its depth are read off the casing tally.", "Confirm that the rows listed close geometrically around the flow source at every depth in the well.", "Read a barrier table, roll each envelope up to a verdict, and turn that pair into a category."]'::jsonb, 3, 'Geometric closure stays with your drawing, and pressure limits belong to the tier that comes after this one.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Chen asks what the next tier adds to the same elements he has been categorising. What is the honest answer?', '["More element kinds and a longer barrier table.", "Limits carrying units, so a verified casing becomes a burst rating held at a stated depth.", "A second scheme run alongside this one, grading the evidence behind each status rather than the condition it reports.", "The geometric closure test this tier declines to perform, computed at last from the element depths."]'::jsonb, 1, 'Nothing on the Associate tier carried a unit, which is what makes its categorical work portable between wells.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 12, 'Yusuf reads a burst rating off a casing tally and calls it the operating limit. What has he missed?', '["The tally quotes the annulus rather than the casing.", "Ratings on a tally are quoted for new pipe, so the figure must be cut by a wear factor before any comparison is drawn.", "An element feels the difference across itself at its own depth, not the pressure standing at surface.", "The tally gives collapse and not burst, and collapse alone governs what an annulus may be operated at."]'::jsonb, 2, 'Change the fluid in the annulus, or the fluid behind the casing, and the allowable surface pressure moves with nothing having happened to the steel.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Sandra watches a test interval lapse on a green well where nothing physical has changed. What follows?', '["Nothing at all, since the hardware is unchanged.", "The element stays verified until a retest returns a poor result, a lapsed interval scheduling work rather than changing a status.", "The element turns not verified, the envelope degrades, and the well moves to yellow on paperwork alone.", "The well turns orange, an expired element being treated as absent from the envelope that used to contain it."]'::jsonb, 2, 'Green is a thing you maintain, and the work that maintains it is the periodic verification programme.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Ines rolls a roster up by hand and gets a different colour from the panel. Where does the module tell her to look first?', '["At the flow potential flag set on the panel.", "At a shared element she counted once, which is the usual cause of a disagreement at this stage.", "At the element kinds, since a kind mistyped on the roster is dropped without any warning being raised anywhere.", "At the order of the rows, because the rollup returns the first status it meets rather than the worst one present."]'::jsonb, 1, 'The seat arithmetic is what exposes it, the gap having to equal the count of rows declared as serving both.'),
  ('integrity', 'beginner', 'module', 'm06-the-associate-reading', 15, 'Dieter is asked to write the whole tier down as one chain of four words. Which chain is right?', '["Element claim, then envelope verdict, then category, then the obligation that colour commits you to.", "Kind, depth, status, then the colour.", "Envelope verdict, then element claim, then obligation, then category, the colour being settled before an action is chosen.", "Element claim, then category, then envelope verdict, the colour telling you how hard to look at each envelope."]'::jsonb, 0, 'Every module in the tier was about evidence, and an envelope verdict is simply the weakest claim that envelope contains.'),
  ('integrity', 'beginner', 'final', null, 1, 'Suppose a supervisor wants the leak rate on the published well''s degraded safety valve so that he can size a repair window. What is available?', '["A rate in litres per minute, computed from the degraded status.", "A leak rate once the annulus fluid density and the seat area have been added to the element record, which the panel allows.", "Nothing of the sort, because a status carries no flow number and the engine holds no time axis at all.", "An estimate of remaining service life, produced by the corrosion model that sits behind the element kinds."]'::jsonb, 2, 'The five refused questions are how fast, how long, how corroded, how likely and how much, and each belongs to another discipline.'),
  ('integrity', 'beginner', 'final', null, 2, 'A team proposes running a flowing well on one exceptionally well tested envelope instead of two. How does the engine treat that plan?', '["It fails the two envelopes check outright, since a well with flow potential carrying one envelope is refused.", "It passes the plan if every element in that envelope is verified.", "It records a warning against the roster and lets the categorisation continue to green, leaving the decision with the operator.", "It downgrades the well by one colour, so an otherwise green well would be reported as yellow instead."]'::jsonb, 0, 'Two barriers exist so that a first failure becomes an event somebody detects and responds to rather than a release.'),
  ('integrity', 'beginner', 'final', null, 3, 'An auditor wants to know which measurement produced the yellow verdict on the teaching well. What should the answer be?', '["A pressure test on the safety valve that fell below its acceptance value.", "A bond log across the production cement interval, read together with the last recorded annulus pressure survey on the well.", "A calculation of the differential the degraded valve could still hold, compared against the reservoir pressure.", "No measurement at all, only one recorded status on one element and a rule about how statuses combine."]'::jsonb, 3, 'The engine accepts elements and statuses rather than opinions, which is what lets two engineers reach the same verdict.'),
  ('integrity', 'beginner', 'final', null, 4, 'Halfway through a plug job the cement will not tag at the depth planned. Does the abandonment builder tell you what to do?', '["Yes, it returns a revised displacement volume for the second attempt.", "No, it is a planning checklist in the well programme tradition and it says nothing about running the job.", "Yes, once the actual tag depth is entered it reissues the phased step list with the affected plug marked for a repeat run.", "Yes, it names the rule that the shortened plug now breaks and then stops."]'::jsonb, 1, 'The builder carries that caveat in its own header, and the barrier half carries the matching one about geometric closure.'),
  ('integrity', 'beginner', 'final', null, 5, 'Finance asks what the phased abandonment programme will cost. What does the output actually contain?', '["A material takeoff in cubic metres of slurry and a count of plugs, with nothing anywhere in it priced.", "A cost per plug, based on the slurry volume each one needs.", "A rig day estimate for each of the three phases, which the operator then multiplies by its own contracted day rate.", "A budget split across the reservoir, intermediate and surface phases of the work."]'::jsonb, 0, 'Pricing is one of five refusals, sitting alongside leak rate, remaining life, corrosion extent and probability of failure.'),
  ('integrity', 'beginner', 'final', null, 6, 'Two functions guarded the same boundary and only one of them checked its caller. Why did that asymmetry matter so much?', '["It made the two functions run at noticeably different speeds.", "It left the element name out of one error message, so a reviewer chasing a bad row had to search the roster by hand instead.", "The trusting half answered green for a word it did not know, failing in the direction integrity must never fail.", "It meant the rollup could be called twice on one envelope without the second call raising anything at all."]'::jsonb, 2, 'Both halves refuse now, and the category error names the other vocabulary and tells you to roll your elements up first.'),
  ('integrity', 'beginner', 'final', null, 7, 'Why does the kind list put a cement plug beside a BOP rather than keeping abandonment hardware separate?', '["Because both are set and tested by the same service company.", "Because a permanent plug does the same job, standing between a pressure source and somewhere it must not go.", "Because the list was assembled alphabetically and those two happen to fall near one another in that ordering.", "Because plugs and preventers share a pressure rating convention, so one field on the element record serves them both."]'::jsonb, 1, 'Abandonment is integrity with nobody left on site to watch it, which is why it shares this engine rather than having its own.'),
  ('integrity', 'beginner', 'final', null, 8, 'A row arrives carrying a name and a kind but the envelope column is blank, and a colleague suggests reading the job off the kind. What happens?', '["The element defaults to the primary envelope until somebody edits it.", "The element is held out of both envelope lists and reported at warn level, so the rest of the roster still categorises.", "The engine assigns it by kind, so a packer is treated as primary and a wellhead as secondary.", "The engine refuses that element by name and stops, because a kind never determines which envelope it serves."]'::jsonb, 3, 'The same packer may be doing a different job in the next well, which is why the assignment is recorded and never inferred.'),
  ('integrity', 'beginner', 'final', null, 9, 'The production casing shows up in the primary rows and again in the secondary rows of the teaching roster. Is that a shared element?', '["Yes, and the common element check reports it on every run.", "Yes, which is why the seat total on this roster runs two seats above the count of distinct items recorded on the sheet.", "No, they are two elements split by the packer, and the seat total still matches the ten pieces of hardware.", "No, because a casing kind is barred from appearing in the secondary envelope in the first place."]'::jsonb, 2, 'Below the packer the string faces reservoir pressure and above it it faces the annulus, so each role carries its own status entry.'),
  ('integrity', 'beginner', 'final', null, 10, 'On an asset where every wellhead routes both envelopes to surface, what does the convention require before that is acceptable?', '["A deliberate written dispensation saying somebody senior knew, why it could not be avoided and what compensates.", "A second wellhead seal, fitted before the well is handed over.", "Nothing at all, since the check sits at warn level and a warning carries no obligation on whoever reads the run report.", "A change to the element record so the wellhead is entered once in the primary and once again in the secondary."]'::jsonb, 0, 'The engine will not take that decision for you, but it names the element on every run so the sharing cannot go unnoticed.'),
  ('integrity', 'beginner', 'final', null, 11, 'Your primary envelope leans on a downhole valve and your secondary leans on a surface valve of the same design. What is the concern?', '["The two valves will need their function tests on the same date.", "The engine will push both valves into the primary list, because a device that shuts cannot serve as a secondary element.", "Nothing, as the drawing shows two separate valves in two separate envelopes.", "Elements from one group fail and are tested the same way, so two of them are weak evidence of independence."]'::jsonb, 3, 'A shared failure mechanism hides better than a shared element, and one cement job that both envelopes rely on is the same trap.'),
  ('integrity', 'beginner', 'final', null, 12, 'Three verified elements are listed in an envelope that leaves the annulus wide open. What verdict comes back?', '["Empty, since an open annulus means the envelope is not closed.", "Intact, because every listed element passed and geometric closure is not something this engine ever checks.", "Degraded, on the grounds that an unclosed envelope carries the same weight as an element nobody has managed to test.", "Failed, because containment that ends in an open path is not containment."]'::jsonb, 1, 'An envelope with nothing in it is caught and rolls up as empty, but one that is populated and not joined is not caught.'),
  ('integrity', 'beginner', 'final', null, 13, 'One wellhead fails. Compare the outcome when it was marked as serving both envelopes with the outcome when only the primary held it.', '["Both envelopes fail at once and the well is red, where one envelope failing alone would have been orange.", "The colour is the same either way, since one element failed.", "Marked both it is orange and marked primary only it is red, because the primary envelope carries the greater weight.", "Marked both it is yellow, since the engine spreads a shared failure across the two envelopes rather than doubling it."]'::jsonb, 0, 'Same element and same failure, two categories apart, and the only difference is how many jobs that element was doing.'),
  ('integrity', 'beginner', 'final', null, 14, 'An associate must say what evidence would support a verified status on a cement plug. Which answer fits the grouping?', '["You function test it, as you would any device that shuts.", "You calculate and then monitor it, as you would a column of fluid standing at the right density in the annulus.", "You log it or you tag it, because things you set to abandon are verified differently from seals and from valves.", "You pressure test the seal it makes against the casing wall, and repeat that test on the interval its kind requires."]'::jsonb, 2, 'Elements in one group tend to fail alike and to be verified alike, which is why fourteen kinds are worth grouping into six.'),
  ('integrity', 'beginner', 'final', null, 15, 'Overnight a test interval expires on a green well and nobody has been anywhere near it. Walk the consequence through.', '["Nothing moves until somebody records a failed test result.", "The element becomes not verified, its envelope becomes degraded and the well reads yellow the next morning.", "The element becomes degraded, its envelope becomes failed and the well drops straight to orange until that test is repeated.", "The element becomes not verified, but the envelope stays intact because no evidence of impairment ever arrived."]'::jsonb, 1, 'Nothing physical happened, and what changed is that the claim you had been making stopped being supportable.'),
  ('integrity', 'beginner', 'final', null, 16, 'Two rosters both come back yellow, one carrying a degraded element and one carrying an untested element. Which output tells them apart?', '["The envelope count, which drops by one on the untested roster.", "The reason sentence returned with the category, which is worded differently for degradation and for a missing test result.", "Nothing in the output, so the two cases have to be told apart from the element list on the original sheet.", "The all verified check, which passes on the degraded roster and fails on the other one, naming the element."]'::jsonb, 3, 'A degraded element needs an intervention while an unverified one needs a test, and that test may well come back clean.'),
  ('integrity', 'beginner', 'final', null, 17, 'An ambiguous result arrives and the engineer writes not verified to avoid deciding between failed and degraded. Does that work?', '["Yes, because not verified is the neutral entry of the four.", "Yes, provided the row is revisited before the next periodic test falls due on that element and on its whole envelope.", "No, since degraded and not verified both give a degraded envelope, so nothing about the call has been avoided.", "No, because an ambiguous result must be entered as failed until a clean repeat test has been produced and filed."]'::jsonb, 2, 'Calling a result failed rather than degraded has the sharpest consequence, since failed ends an envelope''s contribution at once.'),
  ('integrity', 'beginner', 'final', null, 18, 'A spreadsheet export drops the value unknown into one row''s status column. How does envelopeStatus respond?', '["It throws and names the element, since refusing is the only honest response to a word it cannot read.", "It treats the row as not verified and degrades the envelope.", "It skips the row and rolls up the remaining elements, then adds a warning that one status could not be interpreted.", "It maps the row to failed, on the principle that anything unreadable should be assumed to be the worst case."]'::jsonb, 0, 'Every choice such a function could make about that row would be a guess about a barrier, so the name goes in the message.'),
  ('integrity', 'beginner', 'final', null, 19, 'In an eight element envelope the second row is failed and the six behind it are verified. How much of the list gets read?', '["All eight, so that the number of verified rows can be counted.", "All eight of them, because the six verified rows standing behind it lift the envelope back up to degraded rather than failed.", "The first two only, after which the envelope is reported as degraded pending a repeat test on the failed row.", "Only as far as the failed row, where the rollup returns failed and stops without finishing the list."]'::jsonb, 3, 'Nothing left on the list could change the answer, which is the worst element rule written directly into the control flow.'),
  ('integrity', 'beginner', 'final', null, 20, 'A safety valve closes on demand but leaks past its seat above the acceptance criterion. Which status, and why not the harsher one?', '["Degraded, because a valve can never be entered as failed.", "Degraded, because it is a measured shortfall on an element that is still performing part of its job.", "Failed, since any leak past a seat means the element is no longer a barrier however small the rate turns out to be.", "Not verified, since a test that neither clearly passed nor clearly failed leaves the element without usable evidence."]'::jsonb, 1, 'Degraded asserts two things at once, that the element is off specification and that it has not stopped working.'),
  ('integrity', 'beginner', 'final', null, 21, 'A yellow well is handed over with the colour quoted and nothing else. What has the handover lost?', '["The difference between an element somebody inspected and found worn and one nobody has looked at yet.", "The count of elements sitting in each of the two envelopes.", "The reason sentence, which is what tells an incoming engineer whether the degradation sits in the primary or the secondary.", "The flow potential flag, without which an incoming engineer cannot tell whether two envelopes were even required."]'::jsonb, 0, 'Both readings roll up the same way, so the obligation on a yellow well is to work the element list and not the colour.'),
  ('integrity', 'beginner', 'final', null, 22, 'A sheet reports six elements in the primary, six in the secondary and ten distinct items of hardware. What does the arithmetic say?', '["Twelve seats against ten items, so two rows have been dropped.", "The counts are inconsistent and the roster has to be rebuilt, because seats can never exceed the number of physical items.", "Twelve seats against ten items, so exactly two elements are serving both envelopes at the same time.", "Ten items across twelve seats, which is within tolerance and means the envelopes are effectively independent."]'::jsonb, 2, 'Seats minus elements equals the length of the shared list exactly, which is why this is arithmetic and not a judgement.'),
  ('integrity', 'beginner', 'final', null, 23, 'Someone adds three more verified elements to a degraded envelope hoping to lift its verdict. What comes back?', '["Intact, once the verified rows outnumber the degraded one.", "Degraded still, since the rollup looks for the worst status present and never counts how many are verified.", "Degraded, until a fourth verified element is added, at which point the envelope carries enough margin to read intact.", "Intact, because the added elements shorten the path the fluid would have to take through the impaired one."]'::jsonb, 1, 'There is no input for element importance, because anything not load bearing would not have been in the envelope at all.'),
  ('integrity', 'beginner', 'final', null, 24, 'Does it matter whether the degraded row sits at the top or at the bottom of an envelope list?', '["Yes, the first row read sets the verdict for the envelope.", "Yes, since a degraded row at the bottom is reached only after the verified rows above it have already established intact.", "Yes, because the rollup weights rows nearer the pressure source more heavily than rows nearer surface.", "No, the matrix is symmetric about its diagonal and only the worst status present decides the verdict."]'::jsonb, 3, 'The engine run confirms the symmetry across all sixteen two element cases, and the degraded and not verified rows are identical.'),
  ('integrity', 'beginner', 'final', null, 25, 'Somebody passes the string not verified straight into the category function as a primary envelope verdict. What now?', '["It answers green, which is the behaviour that was corrected.", "It maps the string to degraded, since that is the envelope verdict an unverified element would have produced anyway.", "It throws, naming both vocabularies and telling you to roll your elements up into an envelope verdict first.", "It answers yellow, treating an unrecognised word as a degradation for safety."]'::jsonb, 2, 'Before the fix it fell through to the final branch and returned green for a well whose primary envelope nobody had checked.'),
  ('integrity', 'beginner', 'final', null, 26, 'Two barrier tables each show five rows per column. One has a seat gap of zero and the other a gap of two. Which is stronger?', '["The one with no gap, because every seat there has its own hardware rather than one object listed twice.", "The one with the gap, since two elements are doing double duty.", "Neither, because the gap describes only the layout of the table and says nothing about the condition of what is in it.", "They are equal until the statuses are read, since independence is settled by the verdicts and not by the counts."]'::jsonb, 0, 'A table always looks like two envelopes, so the seat gap is what tells you how much of the apparent redundancy is real.'),
  ('integrity', 'beginner', 'final', null, 27, 'A shared element is entered as degraded on an otherwise verified roster. Give the two envelope verdicts and the colour.', '["Primary degraded, secondary intact, so the well is yellow.", "Both envelopes degraded, which the engine escalates to red because the degradation on each of them has a single common cause.", "Both envelopes degraded, and the run is refused outright until the sharing has been removed from the roster.", "Both envelopes read degraded from that one row, so a flowing well comes back yellow with a warning raised."]'::jsonb, 3, 'Its status is read once for each verdict, so the two move together and the second barrier has bought you nothing.'),
  ('integrity', 'beginner', 'final', null, 28, 'A run comes back with no defect reported on any check line and a colour that is not green. What follows?', '["As an inconsistency, so the run should be repeated before filing.", "The checks are a work list of specific defects while the category comes from the rollup, which sees more.", "As a sign that the flow potential flag has been left false, since the checks cannot pass on a well requiring two envelopes.", "As proof the roster is clean, so the colour must have been read off the wrong row of the category table."]'::jsonb, 1, 'There is no check line for a degraded element, so a roster with none of the four listed defects can still be yellow.'),
  ('integrity', 'beginner', 'final', null, 29, 'Clear the flow potential flag on a well with an intact primary and a failed secondary. What colour, and on what reasoning?', '["Green, because once one qualified barrier suffices the engine stops consulting the secondary envelope at all.", "Yellow, since a failed envelope has to count for something.", "Orange, unchanged, because the flag only rescues wells that are short of an envelope rather than wells holding two.", "Green, but only once the failed secondary has been removed from the roster so that it reads as empty instead."]'::jsonb, 0, 'Twelve of the sixteen states change colour when the flag is toggled, and most of those wells have two envelopes present.'),
  ('integrity', 'beginner', 'final', null, 30, 'With the flag off, a well holding nothing at all in its primary comes back green. What does that put on whoever set the flag?', '["Nothing, because an empty envelope is caught by the checks.", "A duty to record the last pressure survey date on the well, after which the engine revalidates the flag on every run.", "The burden of defending a judgement about reservoir pressure, which the engine takes on trust and computes from.", "A second signature from the regulator before the categorisation may be relied on in any report."]'::jsonb, 2, 'A failure that never reaches the colour is still a failure, and the element level checks go on reporting it regardless.'),
  ('integrity', 'beginner', 'final', null, 31, 'Nothing has been recorded in either envelope of a flowing well. Why is the answer orange rather than red?', '["Because red is held back for wells that are actually producing.", "Nothing has been demonstrated to have failed, and the rule that fires is the missing second envelope.", "Because an empty envelope is treated as degraded, and two degraded envelopes have never been worse than orange.", "Because the engine refuses to return red on a roster from which it has read no element statuses at all."]'::jsonb, 1, 'That puts such a well in the same class as one holding a single good envelope, since the scheme categorises what is known.'),
  ('integrity', 'beginner', 'final', null, 32, 'An orange well shows a failed primary against an intact secondary. What is the smallest change that turns it red?', '["A second element in the primary envelope also fails.", "The flow potential flag gets set, which the roster is already carrying because the well was categorised orange to begin with.", "Both envelopes have to fail, since red is reserved for a well with no envelope left standing at all.", "The surviving envelope stops being intact, whether by a degradation, an unverified row or a failure."]'::jsonb, 3, 'Red always needs a failure plus a partner that is not intact, so a failed envelope on its own stays orange.'),
  ('integrity', 'beginner', 'final', null, 33, 'A green well is described as needing no attention until something changes. Where is that description wrong?', '["Green wells still require a monthly annulus pressure bleed down.", "Green obliges the operator to restore a second envelope, which is the same obligation that an orange well carries.", "Green is a claim about evidence and evidence expires, so it is held up by the periodic verification programme.", "Green is the only colour with no obligation attached, so the description is right as long as the roster is not edited."]'::jsonb, 2, 'The day a test interval falls due with no fresh result the element is not verified, its envelope degraded and the well yellow.'),
  ('integrity', 'beginner', 'final', null, 34, 'A manager wants to trend the category quarterly and report that integrity improved by four points. What is the objection?', '["Containment is not a quantity, so there is no partial credit and no way to add two categories together.", "The colours are not published often enough to be trended.", "The trend would be dominated by the flow potential flag, which changes twelve of the sixteen states on its own.", "A trend is acceptable once the four colours have been given numeric weights that the operator has agreed in advance."]'::jsonb, 0, 'Each colour maps to a defined obligation, so reaching one commits somebody to an action rather than to a note in a report.'),
  ('integrity', 'beginner', 'final', null, 35, 'Only four of the sixteen states hold their colour when flow potential is toggled. Which comfortable reading does that destroy?', '["That the category table is symmetric about its diagonal.", "That the secondary envelope decides the colour whenever it happens to be worse than the primary envelope on that well.", "That an empty envelope and a failed envelope are read as the same thing by the categorisation in either case.", "That the flag matters only where an envelope is missing, since twelve wells holding two envelopes move as well."]'::jsonb, 3, 'With the flag off the colour is a function of the primary alone, and an empty primary reads green there just as intact does.'),
  ('integrity', 'beginner', 'final', null, 36, 'Ada''s sheet gives five in the primary, five in the secondary, eight distinct items and every row verified on a flowing well. What does she report?', '["Yellow, because two elements are serving both envelopes.", "Green, with two shared elements named, since the sharing is a warning and both envelopes still read intact.", "Orange, since ten seats against eight items means the well is two barriers short of the two it is required to hold.", "The run is refused, because the seat total and the item count do not agree with one another on her sheet."]'::jsonb, 1, 'The seat gap tells you what you have while the statuses tell you its condition, and only the second of those reaches the colour.'),
  ('integrity', 'beginner', 'final', null, 37, 'Two rows are left off a submitted roster because their test certificates could not be found. What has the omission done?', '["It manufactures a cleaner colour, where entering them as not verified would have made the envelope degraded.", "Nothing, since an element with no certificate is not a barrier.", "It shortens the primary count by two, which the seat arithmetic then flags because the roster length no longer matches.", "It leaves the colour untouched but causes the all verified check to fail, naming the two rows that were dropped."]'::jsonb, 0, 'The honest entry when you cannot produce the paper is not verified, and that costs you the whole envelope rather than one row.'),
  ('integrity', 'beginner', 'final', null, 38, 'A producing well is being handed to the abandonment team. How much of the associate reading survives that handover?', '["Only the element statuses, since envelopes end with production.", "None of it, because abandonment is categorised by plug rule checks rather than by the envelope and category chain.", "All of it, because one barrier vocabulary covers drilling, production and abandonment, and plugs are elements too.", "The category alone, which the abandonment programme carries forward as its starting condition for the phased work."]'::jsonb, 2, 'Abandonment is the second half of this engine rather than a separate subject, and it is integrity with nobody left to watch.'),
  ('integrity', 'beginner', 'final', null, 39, 'Every row on a table reads verified, but three carry test dates that fell outside their interval months ago. What is the honest verdict?', '["Intact, because the recorded status on each row still says verified.", "Those three are not verified, so the envelope holding them is degraded and the well cannot be green.", "Failed, since a test that has aged out is treated in exactly the same way as a test that came back bad on the day it ran.", "Intact for now, with the three rows carried as a warning until the next verification campaign clears them."]'::jsonb, 1, 'Verified is a claim about a document that has not aged out, so an expiry moves the row with nobody touching the well.'),
  ('integrity', 'beginner', 'final', null, 40, 'Without opening the panel, state what a flowing well with a failed secondary row and an otherwise verified primary obliges.', '["Yellow, so record the degradation and set a restoration date.", "Green, once the primary has been demonstrated intact and the failed row has been scheduled into the next replacement campaign.", "Red, so shut in and intervene at once, because a failed envelope leaves nothing at all that can be stood behind.", "Orange, so restore the second envelope or take the flow potential away by killing or securing the well."]'::jsonb, 3, 'Continued production on a single barrier is a decision that belongs a long way above the well site.'),
  ('integrity', 'beginner', 'final', null, 41, 'Which part of this tier''s work is left to the engineer''s pencil rather than to the engine?', '["Whether the listed elements actually form a sealed surface around the source, which is geometric closure.", "Whether the roster holds any element with no envelope assigned.", "Whether the seat total agrees with the count of distinct hardware, which always has to be done by hand before the panel.", "Whether the two envelope verdicts have been combined with the flow potential flag in the right order on the sheet."]'::jsonb, 0, 'Sketch the well, mark the source, draw the two loops, and write the element list from what your pencil crossed.'),
  ('integrity', 'beginner', 'final', null, 42, 'Before any pressure limit can be worked on an element at the next tier, what three things have to be in the well file?', '["Its rating, its kind and the envelope it has been assigned to.", "Its rating, the reservoir pressure and the acceptance criterion the last periodic test on that element was held to.", "Its rating, the depth at which it sits, and the fluid standing on each side of it at that depth.", "Its rating, its status and the date on which its current verification is due to expire on the programme."]'::jsonb, 2, 'An element feels the difference between its two sides at its own depth, which is why a tally rating is not an operating limit.');
